        ("Производительность", "go", "Напишите функцию ProcessAll(ctx context.Context, items []string, limit int, fn func(context.Context, string) error) error, которая обрабатывает элементы параллельно не более limit одновременно с помощью errgroup и возвращает первую ошибку.",
         "package main\n\nimport (\n    \"context\"\n\n    \"golang.org/x/sync/errgroup\"\n)\n\nfunc ProcessAll(ctx context.Context, items []string, limit int, fn func(context.Context, string) error) error {\n    g, ctx := errgroup.WithContext(ctx)\n    g.SetLimit(limit)\n    for _, it := range items {\n        g.Go(func() error {\n            return fn(ctx, it)\n        })\n    }\n    return g.Wait()\n}"),
